     8→SemaType *sema_type_basic(SemaTypeKind kind) {
     9→    SemaType *t = (SemaType *)malloc(sizeof(SemaType));
    10→    if (!t) return NULL;
    11→    t->kind = kind;
    12→    t->base = NULL;
    13→    t->array_size = 0;
    14→    t->is_const = 0;
    15→    return t;
    16→}
    17→
    18→SemaType *sema_type_ptr(SemaType *base) {
    19→    if (!base) return NULL;
    20→    SemaType *t = (SemaType *)malloc(sizeof(SemaType));
    21→    if (!t) return NULL;
    22→    t->kind = SEMA_TYPE_PTR;
    23→    t->base = base;
    24→    t->array_size = 0;
    25→    t->is_const = 0;
    26→    return t;
    27→}
    28→
    29→SemaType *sema_type_array(SemaType *base, int size) {
    30→    if (!base) return NULL;
    31→    SemaType *t = (SemaType *)malloc(sizeof(SemaType));
    32→    if (!t) return NULL;
    33→    t->kind = SEMA_TYPE_ARRAY;
    34→    t->base = base;
    35→    t->array_size = size;
    36→    t->is_const = 0;
    37→    return t;
    38→}
    39→
    40→void sema_type_free(SemaType *t) {
    41→    if (!t) return;
    42→    if (t->base) sema_type_free(t->base);
    43→    free(t);
    44→}
    45→
    46→int sema_types_compatible(SemaType *a, SemaType *b) {
    47→    if (!a || !b) return 0;
    48→    if (a->kind != b->kind) {
    49→        /* 기본형은 상호 변환 가능 (int/char/float/double) */
    50→        if ((a->kind == SEMA_TYPE_INT || a->kind == SEMA_TYPE_CHAR) &&
    51→            (b->kind == SEMA_TYPE_INT || b->kind == SEMA_TYPE_CHAR)) return 1;
    52→        if ((a->kind == SEMA_TYPE_FLOAT || a->kind == SEMA_TYPE_DOUBLE) &&
    53→            (b->kind == SEMA_TYPE_FLOAT || b->kind == SEMA_TYPE_DOUBLE)) return 1;
    54→        return 0;
    55→    }
    56→    /* 같은 종류 */
    57→    if (a->kind == SEMA_TYPE_PTR) {
    58→        return sema_types_compatible(a->base, b->base);
    59→    }
    60→    if (a->kind == SEMA_TYPE_ARRAY) {
    61→        return a->array_size == b->array_size && sema_types_compatible(a->base, b->base);
    62→    }
    63→    return 1;
    64→}
