    66→const char *sema_type_to_string(SemaType *t) {
    67→    if (!t) return "unknown";
    68→    switch (t->kind) {
    69→        case SEMA_TYPE_VOID: return "void";
    70→        case SEMA_TYPE_CHAR: return "char";
    71→        case SEMA_TYPE_INT: return "int";
    72→        case SEMA_TYPE_FLOAT: return "float";
    73→        case SEMA_TYPE_DOUBLE: return "double";
    74→        case SEMA_TYPE_LONG: return "long";
    75→        case SEMA_TYPE_PTR: return "ptr";
    76→        case SEMA_TYPE_ARRAY: return "array";
    77→        case SEMA_TYPE_FUNC: return "func";
    78→        case SEMA_TYPE_STRUCT: return "struct";
    79→        case SEMA_TYPE_UNKNOWN: return "unknown";
    80→    }
    81→    return "unknown";
    82→}
